import React from 'react';
import {NavigationContainer} from '@react-navigation/native';
import {createBottomTabNavigator} from '@react-navigation/bottom-tabs';
import {Text,View} from 'react-native';
const T=createBottomTabNavigator();
const Screen=({n}:{n:string})=>(<View style={{flex:1,alignItems:'center',justifyContent:'center'}}><Text>{n}</Text></View>);
export default function App(){return(<NavigationContainer><T.Navigator>
<T.Screen name='{{tab1}}'>{()=><Screen n='{{tab1}}'/>}</T.Screen>
<T.Screen name='{{tab2}}'>{()=><Screen n='{{tab2}}'/>}</T.Screen>
<T.Screen name='{{tab3}}'>{()=><Screen n='{{tab3}}'/>}</T.Screen>
</T.Navigator></NavigationContainer>);}
